"""Validate and render the discovery-selected D10 true-breakout confirmation."""
from __future__ import annotations
import argparse,json
from datetime import timedelta
from pathlib import Path
import pandas as pd
def metrics(frame):
 truth=frame.direct_true.astype(str).str.lower().eq("true");confirmed=frame.confirmation_complete_10.astype(str).str.lower().eq("true")&frame.held_abs_10.astype(str).str.lower().eq("true")&frame.held_rel_10.astype(str).str.lower().eq("true")&frame.progress_return_10.ge(.07)&frame.progress_active_10.ge(.03);count=int(confirmed.sum());true=int((confirmed&truth).sum());remaining_return=(1+frame.loc[confirmed,"future20"])/(1+frame.loc[confirmed,"progress_return_10"])-1;remaining_active=(1+frame.loc[confirmed,"future_active20"])/(1+frame.loc[confirmed,"progress_active_10"])-1;return {"signals":len(frame),"true_breakouts":int(truth.sum()),"confirmed":count,"confirmed_true":true,"precision":true/count if count else 0.0,"recall":true/int(truth.sum()) if truth.sum() else 0.0,"base_true_rate":float(truth.mean()),"precision_lift":true/count/float(truth.mean()) if count and truth.mean() else 0.0,"remaining_return_median":float(remaining_return.median()) if count else None,"remaining_active_median":float(remaining_active.median()) if count else None}
def run(features_path,out_json,out_md,current_json,current_md):
 x=pd.read_csv(features_path);periods={name:metrics(x[x.year.between(a,b)]) for name,a,b in [("2018-2022",2018,2022),("2023-2024",2023,2024),("2025",2025,2025)]};overall=metrics(x[x.year.between(2018,2025)]);checks={"validation_signals":periods["2023-2024"]["confirmed"]>=15,"holdout_signals":periods["2025"]["confirmed"]>=8,"overall_precision":overall["precision"]>=.55,"validation_precision":periods["2023-2024"]["precision"]>=.55,"holdout_precision":periods["2025"]["precision"]>=.55,"overall_recall":overall["recall"]>=.20,"validation_recall":periods["2023-2024"]["recall"]>=.20,"holdout_recall":periods["2025"]["recall"]>=.20,"remaining_return":overall["remaining_return_median"]>0,"remaining_active":overall["remaining_active_median"]>0};payload={"study":"a-share-true-breakout-confirmation-v5","method":"hold both D0 breakout levels through D10, D10 sector return>=7%, D10 active>=3%","label":"D0 forward10>=4%, forward20>=8%, relative20>=4%","overall":overall,"periods":periods,"checks":checks,"verdict":"GO-TRUE-BREAKOUT-CONFIRMATION" if all(checks.values()) else "NO-GO","trade_authorized":False};Path(out_json).write_text(json.dumps(payload,ensure_ascii=False,indent=2)+"\n");lines=["# A股真突破确认V5结果","",f"- verdict: **{payload['verdict']}**",f"- overall precision/recall/lift: {overall['precision']:.2%} / {overall['recall']:.2%} / {overall['precision_lift']:.2f}x",f"- 2023-2024 precision/recall: {periods['2023-2024']['precision']:.2%} / {periods['2023-2024']['recall']:.2%}",f"- 2025 precision/recall: {periods['2025']['precision']:.2%} / {periods['2025']['recall']:.2%}",f"- remaining return/active median: {overall['remaining_return_median']:.2%} / {overall['remaining_active_median']:.2%}","- trade authorized: **NO**"];Path(out_md).write_text("\n".join(lines)+"\n");latest=pd.to_datetime(x.signal_date).max();current=x[pd.to_datetime(x.signal_date).ge(latest-timedelta(days=50))].copy();complete=current.confirmation_complete_10.astype(str).str.lower().eq("true");held=current.held_abs_10.astype(str).str.lower().eq("true")&current.held_rel_10.astype(str).str.lower().eq("true");confirmed=complete&held&current.progress_return_10.ge(.07)&current.progress_active_10.ge(.03);current["status"]="PENDING_D10";current.loc[complete&~held,"status"]="FALSE_BREAKOUT_REJECTED";current.loc[complete&held&~confirmed,"status"]="UNCONFIRMED_BREAKOUT";current.loc[confirmed,"status"]="TRUE_BREAKOUT_CONFIRMED";records=current[["signal_date","sector","status","progress_return_10","progress_active_10"]].sort_values(["signal_date","sector"]).to_dict("records");current_payload={"as_of":latest.date().isoformat(),"method_verdict":payload["verdict"],"trade_authorized":False,"signals":records};Path(current_json).write_text(json.dumps(current_payload,ensure_ascii=False,indent=2)+"\n");current_lines=["# A股真突破当前确认","",f"- as of: {latest.date().isoformat()}",f"- method: **{payload['verdict']}**","- trade authorized: **NO**",""]+[f"- {r['signal_date']} {r['sector']}: {r['status']}" for r in records];Path(current_md).write_text("\n".join(current_lines)+"\n");print("\n".join(lines));return payload
def main(argv=None):
 p=argparse.ArgumentParser();p.add_argument("--features",default="overall/a-share-sector-true-breakout-features.csv");p.add_argument("--out-json",default="overall/a-share-true-breakout-confirmation-v5-result.json");p.add_argument("--out-md",default="overall/a-share-true-breakout-confirmation-v5-result.md");p.add_argument("--current-json",default="overall/a-share-true-breakout-current.json");p.add_argument("--current-md",default="overall/a-share-true-breakout-current.md");a=p.parse_args(argv);run(a.features,a.out_json,a.out_md,a.current_json,a.current_md);return 0
if __name__=="__main__":raise SystemExit(main())
